try{if(window.location.pathname.indexOf('merci')!==-1||window.location.pathname.indexOf('thank')!==-1){sendGtag('purchase',{transaction_id:window.location.search.match(/order=([^&]+)/)?.[1]||'unknown',value:1,currency:'EUR',method:'site',event_category:'conversion',event_label:'merci_page'});console.log('✅ purchase event sent (merci)')}}catch(e){console.warn('merci event error',e)}
